package enc

import (
	"fmt"
	"testing"

	"sip/pkg/sipmsg"

	"github.com/stretchr/testify/assert"
)

func Test_encoder_Encode(t *testing.T) {
	tests := getEncoderTestCases()
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e := NewEncoder(WithHeadersOrder(DefaultHeadersSortOrderFunc))
			got, err := e.Encode(tt.msg)
			assert.Equal(t, tt.wantErr, err != nil, fmt.Sprintf("Encode(%v), err: %v", tt.msg, err))
			assert.Equal(t, tt.want, got)
		})
	}
}

type encoderTestCase struct {
	name    string
	msg     *sipmsg.GenericMessage
	want    []byte
	wantErr bool
}

func getEncoderTestCases() []encoderTestCase {
	cases := make([]encoderTestCase, 0)
	cases = append(cases, getRegisterMsgEncoderTestCase())
	cases = append(cases, getNotImplementedMsgEncoderTestCase())
	cases = append(cases, getOKMsgEncoderTestCase())
	cases = append(cases, getUnauthorizedMsgEncoderTestCase())
	cases = append(cases, getAcceptedMsgEncoderTestCase())
	cases = append(cases, getSubscribeMsgEncoderTestCase())
	cases = append(cases, getOptionsMsgEncoderTestCase())
	cases = append(cases, getNotifyMsgEncoderTestCase())
	return cases
}

